  const result = await generateText({
    model,
    instructions: ORDER_RULES,
    tools: { orderLookup },
    toolsContext: { customerId },
    stopWhen: isStepCount(4),
    prompt: question,
  });
  return { text: result.text, toolsUsed: result.toolCalls.map((c) => c.toolName) };
}

